1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	import Activity from "./pages/Activity";
24	
25	// Sidebar-accessible pages — eager to avoid flash on click
26	import Changelog from "./pages/Changelog";
27	import RequestFeature from "./pages/RequestFeature";
28	import CareerSettings from "./pages/CareerSettings";
29	
30	// Lazy imports — infrequent or large pages
31	const Admin = lazy(() => import("./pages/Admin"));
32	const NotFound = lazy(() => import("./pages/NotFound"));
33	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
34	const BookDemo = lazy(() => import("./pages/BookDemo"));
35	const Apply = lazy(() => import("./pages/Apply"));
36	const CareerPage = lazy(() => import("./pages/CareerPage"));
37	const CareerJobDetail = lazy(() => import("./pages/CareerJobDetail"));
38	const LandingPage = lazy(() => import("@/components/LandingPage"));
39	const SharedPortal = lazy(() => import("./pages/SharedPortal"));
40	const BookInterview = lazy(() => import("./pages/BookInterview"));
41	
42	const queryClient = new QueryClient({
43	  defaultOptions: {
44	    queries: {
45	      staleTime: 5 * 60 * 1000,
46	      gcTime: 10 * 60 * 1000,
47	      refetchOnWindowFocus: false,
48	      refetchOnMount: false,
49	      retry: 1,
50	    },
51	  },
52	});
53	
54	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
55	const PageLoader = () => (
56	  <div className="flex h-svh w-full overflow-hidden">
57	    {/* Sidebar skeleton — matches sidebar width */}
58	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
59	      <div className="px-4 py-4">
60	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
61	      </div>
62	      <div className="border-t border-border" />
63	      <div className="p-3 space-y-2">
64	        {[1, 2, 3, 4].map((i) => (
65	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
66	        ))}
67	      </div>
68	    </div>
69	    {/* Content area skeleton */}
70	    <div className="flex-1 flex flex-col min-w-0">
71	      {/* Header skeleton */}
72	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
73	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
74	        <div className="flex items-center gap-3">
75	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
76	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
77	        </div>
78	      </div>
79	      {/* Body skeleton */}
80	      <div className="flex-1 overflow-y-auto p-6">
81	        <div className="max-w-5xl mx-auto space-y-4">
82	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
83	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
84	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
85	            {[1, 2, 3, 4].map((i) => (
86	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
87	            ))}
88	          </div>
89	        </div>
90	      </div>
91	    </div>
92	  </div>
93	);
94	
95	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
96	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
97	  const { isAdmin, loading } = useAuth();
98	
99	  // Don't block rendering while loading — only gate when we know maintenance is on
100	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
101	  return <>{children}</>;
102	};
103	
104	const RootRoute = () => {
105	  const { user, loading } = useAuth();
106	  if (loading) return <PageLoader />;
107	  return user ? <Index /> : <LandingPage />;
108	};
109	
110	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
111	const DataPrefetcher = () => {
112	  const { user } = useAuth();
113	  const qc = useQueryClient();
114	
115	  useEffect(() => {
116	    // Prefetch public data that doesn't require auth
117	    qc.prefetchQuery({
118	      queryKey: ["changelog_public"],
119	      queryFn: async () => {
120	        const { data } = await (supabase as any)
121	          .from("changelog")
122	          .select("id, version, title, description, category, published_at")
123	          .eq("status", "published")
124	          .order("published_at", { ascending: false });
125	        return data ?? [];
126	      },
127	      staleTime: 5 * 60 * 1000,
128	    });
129	    qc.prefetchQuery({
130	      queryKey: ["feature_requests"],
131	      queryFn: async () => {
132	        const { data } = await (supabase as any)
133	          .from("feature_requests")
134	          .select("*")
135	          .order("created_at", { ascending: false });
136	        return data ?? [];
137	      },
138	      staleTime: 5 * 60 * 1000,
139	    });
140	  }, []);
141	
142	  useEffect(() => {
143	    if (!user) return;
144	    qc.prefetchQuery({
145	      queryKey: ["my_feature_votes"],
146	      queryFn: async () => {
147	        const { data } = await (supabase as any)
148	          .from("feature_request_votes")
149	          .select("feature_request_id")
150	          .eq("user_id", user.id);
151	        return (data ?? []).map((v: any) => v.feature_request_id);
152	      },
153	      staleTime: 5 * 60 * 1000,
154	    });
155	  }, [user?.id]);
156	
157	  return null;
158	};
159	
160	const App = () => (
161	  <QueryClientProvider client={queryClient}>
162	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
163	      <AuthProvider>
164	        <DataPrefetcher />
165	        <TooltipProvider>
166	          <Sonner />
167	          <BrowserRouter>
168	            <SeoHead />
169	            <Suspense fallback={<PageLoader />}>
170	              <Routes>
171	                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
172	                <Route path="/apply/:jobId" element={<Apply />} />
173	                <Route path="/careers/:slug" element={<CareerPage />} />
174	                <Route path="/careers/:slug/jobs/:jobId" element={<CareerJobDetail />} />
175	                <Route path="/shared/:token" element={<SharedPortal />} />
176	                <Route path="/book/:token" element={<BookInterview />} />
177	                <Route path="*" element={
178	                  <MaintenanceGate>
179	                    <Routes>
180	                      <Route path="/auth" element={<Auth />} />
181	                      <Route path="/" element={<RootRoute />} />
182	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
183	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
184	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
185	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
186	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
187	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
188	                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
189	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
190	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
191	                      <Route path="/book-demo" element={<BookDemo />} />
192	                      <Route path="/request-feature" element={<RequestFeature />} />
193	                      <Route path="/changelog" element={<Changelog />} />
194	                      <Route path="/payment/callback" element={<PaymentCallback />} />
195	                      <Route path="*" element={<NotFound />} />
196	                    </Routes>
197	                  </MaintenanceGate>
198	                } />
199	              </Routes>
200	            </Suspense>
201	            <ChatWidget />
202	          </BrowserRouter>
203	        </TooltipProvider>
204	      </AuthProvider>
205	    </ThemeProvider>
206	  </QueryClientProvider>
207	);
208	
209	export default App;
210	
